CREATE FUNCTION public.quiz_award(p_prize uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.quiz_prizes; winner uuid; BEGIN SELECT * INTO p FROM public.quiz_prizes WHERE id=p_prize FOR UPDATE; IF NOT FOUND OR p.awarded_at IS NOT NULL THEN RAISE EXCEPTION 'Lot introuvable ou déjà attribué'; END IF; IF now()<=p.ends_at THEN RAISE EXCEPTION 'Le concours n’est pas terminé'; END IF; SELECT t.user_id INTO winner FROM public.transactions t LEFT JOIN (SELECT user_id,sum(earned)/10 AS score FROM public.quiz_sessions WHERE created_at BETWEEN p.starts_at AND p.ends_at GROUP BY user_id) s ON s.user_id=t.user_id WHERE t.kind='forfait' AND t.status='success' AND t.created_at BETWEEN p.starts_at AND p.ends_at GROUP BY t.user_id,s.score ORDER BY count(*) DESC,coalesce(s.score,0) DESC,t.user_id ASC LIMIT 1; IF winner IS NULL THEN RAISE EXCEPTION 'Aucun participant éligible'; END IF; UPDATE public.quiz_prizes SET winner_id=winner,awarded_at=now() WHERE id=p.id; RETURN winner; END $$; REVOKE ALL ON FUNCTION public.quiz_award(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.quiz_award(uuid) TO service_role;